#!/usr/bin/env python3
"""
Generates auth/supabase-config.js from CI environment variables,
and stamps service-worker.js with an auto-incrementing cache version.
Called by GitHub Actions deploy.yml — do not run manually.

Required env vars (set as REPOSITORY secrets in GitHub):
  SUPABASE_URL      https://xxxx.supabase.co
  SUPABASE_ANON     your-anon-public-key
  VAPID_PUBLIC_KEY  your VAPID EC public key (safe to embed, not secret)

Auto-injected by GitHub Actions (no config needed):
  GITHUB_SHA        full commit SHA — first 7 chars used as build tag
"""
import json
import os
import re
import subprocess
import sys
import time
from datetime import date

url          = os.environ.get("SUPABASE_URL",     "").strip()
anon         = os.environ.get("SUPABASE_ANON",    "").strip()
vapid_pubkey = os.environ.get("VAPID_PUBLIC_KEY", "").strip()

# ── Validate ──────────────────────────────────────────────────────────────────
if not url.startswith("https://"):
    print("::error::SUPABASE_URL is missing or not a valid https URL.", file=sys.stderr)
    print("  Got: " + repr(url[:30]), file=sys.stderr)
    print("  Fix: repo Settings → Secrets → Actions → New repository secret → SUPABASE_URL", file=sys.stderr)
    sys.exit(1)

if len(anon) < 20:
    print("::error::SUPABASE_ANON is missing or too short.", file=sys.stderr)
    print("  Fix: repo Settings → Secrets → Actions → New repository secret → SUPABASE_ANON", file=sys.stderr)
    sys.exit(1)

if len(vapid_pubkey) < 10:
    print("::warning::VAPID_PUBLIC_KEY is missing — push notifications will not work.", file=sys.stderr)
    print("  Fix: repo Settings → Secrets → Actions → New repository secret → VAPID_PUBLIC_KEY", file=sys.stderr)

# ── Build & Version Info ──────────────────────────────────────────────────────
sha           = os.environ.get("GITHUB_SHA", "local")[:7]
build_date    = date.today().strftime("%Y%m%d")
cache_version = "lm-v" + build_date + "." + sha

# ── Generate auth/supabase-config.js ──────────────────────────────────────────
lines = [
    "// Auto-generated by GitHub Actions — do not commit or edit manually",
    "var SUPABASE_URL      = " + json.dumps(url)          + ";",
    "var SUPABASE_ANON     = " + json.dumps(anon)         + ";",
    "var VAPID_PUBLIC_KEY  = " + json.dumps(vapid_pubkey) + ";",
    "var LM_DEPLOY_ID      = " + json.dumps(cache_version)+ ";",
    "window.LM_DEPLOY_ID   = LM_DEPLOY_ID;",
    "var _supabase = (function () {",
    "  if (!SUPABASE_URL.startsWith('https://') || SUPABASE_ANON.length < 20) {",
    "    console.error('[LM] supabase-config.js: credentials not configured correctly.');",
    "    return undefined;",
    "  }",
    "  return window['supabase'].createClient(SUPABASE_URL, SUPABASE_ANON, {",
    "    auth: {",
    "      persistSession    : true,",
    "      autoRefreshToken  : true,",
    "      detectSessionInUrl: true",
    "    }",
    "  });",
    "}());",
    "",
]

content = "\n".join(lines)

with open("auth/supabase-config.js", "w") as f:
    f.write(content)

print("✅  auth/supabase-config.js generated (" + str(len(content)) + " bytes)")
print("    URL: " + url[:45] + "...")
print("    Deploy ID: " + cache_version)

# ── Write version.json ────────────────────────────────────────────────────────
github_repo = os.environ.get("GITHUB_REPOSITORY", "JeeventhiranV/LedgerMate")

# The APK build workflow (build-apk.yml) is responsible for building APKs and releasing them.
# When a web patch or web build runs (deploy.yml via gen_config.py), we MUST NOT increment
# the APK version code, because no new APK was built!
# Instead, we read the authoritative latest released APK version from GitHub Releases.

apk_version_code = 354
apk_version_name = "1.0.354"
apk_download_url = f"https://github.com/{github_repo}/releases/download/latest/app-release.apk"
release_notes = "Feature updates, security enhancements, UI improvements, and bug fixes."

# 1. Read existing version.json files as baseline
for v_file in ["version.json", "study/version.json"]:
    if os.path.exists(v_file):
        try:
            with open(v_file, "r") as f:
                old_ver = json.load(f)
                old_code = int(old_ver.get("apkVersionCode", 0))
                if old_code > 0:
                    apk_version_code = old_code
                    if old_ver.get("apkVersionName"):
                        apk_version_name = old_ver.get("apkVersionName")
                    if old_ver.get("apkDownloadUrl"):
                        apk_download_url = old_ver.get("apkDownloadUrl")
                    if old_ver.get("releaseNotes"):
                        release_notes = old_ver.get("releaseNotes")
                    break
        except Exception as e:
            print(f"Notice reading {v_file}: {e}")

# 2. Query GitHub Releases for the actual latest published APK release
try:
    import urllib.request
    rel_url = f"https://github.com/{github_repo}/releases/download/latest/version.json"
    req = urllib.request.Request(rel_url, headers={"User-Agent": "LedgerMate-CI"})
    with urllib.request.urlopen(req, timeout=6) as resp:
        if resp.status == 200:
            rel_ver = json.loads(resp.read().decode())
            code = int(rel_ver.get("apkVersionCode", 0))
            if code > 0:
                apk_version_code = code
                apk_version_name = rel_ver.get("apkVersionName", f"1.0.{code}")
                apk_download_url = rel_ver.get("apkDownloadUrl", apk_download_url)
                if rel_ver.get("releaseNotes"):
                    release_notes = rel_ver.get("releaseNotes")
                print(f"✅ Synced with latest published APK release: v{apk_version_name} (code: {apk_version_code})")
except Exception as e:
    print(f"Notice fetching release version.json: {e} (using baseline {apk_version_code})")

# 3. Environment override (used only when an explicit APK build number is supplied)
env_build = os.environ.get("APK_BUILD_NUMBER")
if env_build and env_build.strip().isdigit():
    apk_version_code = int(env_build.strip())
    apk_version_name = f"1.0.{apk_version_code}"

version_info = {
    "version": cache_version,
    "commit": sha,
    "build_date": build_date,
    "timestamp": int(time.time() * 1000),
    "apkVersionCode": apk_version_code,
    "apkVersionName": apk_version_name,
    "apkDownloadUrl": apk_download_url,
    "releaseNotes": release_notes
}
with open("version.json", "w") as f:
    json.dump(version_info, f, indent=2)

if os.path.exists("study"):
    with open("study/version.json", "w") as f:
        json.dump(version_info, f, indent=2)

print("✅  version.json generated → " + cache_version + " (APK v" + apk_version_name + ", versionCode: " + str(apk_version_code) + ")")

# ── Stamp service-worker.js with auto cache version ──────────────────────────
sw_path = "service-worker.js"
with open(sw_path, "r") as f:
    sw = f.read()

sw_patched = re.sub(
    r"const CACHE_VERSION = 'lm-v[^']*';",
    "const CACHE_VERSION = '" + cache_version + "';",
    sw
)

with open(sw_path, "w") as f:
    f.write(sw_patched)

print("✅  service-worker.js cache version → " + cache_version)
